		private static int GetMaxLvMonsTblNo(global::MonsLv[] inEncCommonData, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, int inTblNo) {
            if (inFldSpa.Egg)
                return inTblNo;
            if (inFldSpa.Spa != TokuseiNo.PURESSYAA && inFldSpa.Spa != TokuseiNo.HARIKIRI && inFldSpa.Spa != TokuseiNo.YARUKI)
                return inTblNo;
            if (RandomGroupWork.RandomValue(2) == 0)
                return inTblNo;

            // 019b6694..019b69f0: unrolled over 12 entries
            for (int i = 0; i < 12; i++)
            {
                if (inEncCommonData[i].monsNo == inEncCommonData[inTblNo].monsNo && inEncCommonData[i].maxlv > inEncCommonData[inTblNo].maxlv)
                    inTblNo = i;
            }
            return inTblNo;
        }
		private static void SetSpaStruct(global::Pml.PokePara.PokemonParam inPokeParam, global::XLSXContent.FieldEncountTable.Sheettable inData, ref global::Dpr.Field.FieldEncount.ENC_FLD_SPA outSpa) {
            if (inPokeParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                outSpa.Egg = true;
                outSpa.Spa = TokuseiNo.MAX;
            }
            else
            {
                outSpa.Egg = false;
                outSpa.Spa = inPokeParam.GetTokuseiNo();
            }

            outSpa.SpMyLv = 0;
            outSpa.SprayCheck = false;
            outSpa.EncCancelSpInvalid = false;
            outSpa.FormProb = new int[2];
            if (inData != null)
            {
                outSpa.FormProb[0] = inData.FormProb[0];
                outSpa.FormProb[1] = inData.FormProb[1];
                outSpa.AnnoonTblType = inData.AnnoonTable[1] - 1;
            }
        }
		private static uint ChangeEncProb(bool inIsFishing, uint inProb, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::SYS_WEATHER inWeatherCode, global::Pml.PokePara.PokemonParam inPokeParam) {
            if (inFldSpa.Egg)
                return inProb;

            if (inIsFishing)
            {
                switch (inFldSpa.Spa)
                {
                    case TokuseiNo.KYUUBAN:
                    case TokuseiNo.NENTYAKU:
                        inProb = 100;
                        break;
                }
            }
            else
            {
                // byte jump table @03d59e3a covers TokuseiNo 71..99
                switch (inFldSpa.Spa)
                {
                    case TokuseiNo.AKUSYUU:
                    case TokuseiNo.SIROIKEMURI:
                    case TokuseiNo.HAYAASI:
                    case TokuseiNo.SURINUKE:
                        inProb /= 2;
                        break;

                    case TokuseiNo.HAKKOU:
                    case TokuseiNo.ARIZIGOKU:
                    case TokuseiNo.NOOGAADO:
                        inProb *= 2;
                        break;

                    case TokuseiNo.SUNAGAKURE:
                        if (inWeatherCode == SYS_WEATHER.SANDSTORM)
                            inProb /= 2;
                        break;

                    case TokuseiNo.YUKIGAKURE:
                        if (inWeatherCode == SYS_WEATHER.SNOW || inWeatherCode == SYS_WEATHER.SNOWSTORM || inWeatherCode == SYS_WEATHER.SNOWSTORM_H)
                            inProb /= 2;
                        break;
                }
            }

            if (inProb > 100)
                inProb = 100;

            return inProb;
        }
		private static bool CheckEcntCancelByLv(global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::Pml.PokePara.PokemonParam inMyPokeParam, int inEneLv) {
            if (inFldSpa.EncCancelSpInvalid || inFldSpa.Egg)
                return false;

            if (inFldSpa.Spa != TokuseiNo.SURUDOIME && inFldSpa.Spa != TokuseiNo.IKAKU)
                return false;

            uint myLv = inMyPokeParam.GetLevel();
            if (myLv < 6)
                return false;

            if (inEneLv > myLv - 5)
                return false;

            if (RandomGroupWork.RandomValue(2) != 0)
                return false;

            return true;
        }
		private static bool CheckSpray(int inEneLv, ref global::Dpr.Field.FieldEncount.ENC_FLD_SPA inSpa) {
            if (inSpa.SprayCheck && inSpa.SpMyLv > inEneLv)
                return true;

            return false;
        }
		private static uint ChangeEncProbByEquipItem(global::Pml.PokePara.PokemonParam inMyPokeParam, uint ioPer) {
            ushort item = inMyPokeParam.GetItem();
            if (item == (ushort)ItemNo.KIYOMENOOKOU || item == (ushort)ItemNo.KIYOMENOOHUDA)
                ioPer = ioPer * 2 / 3;

            return ioPer;
        }
