		private static bool MapEncountCheck(uint per, int attr, bool inGridmove) {
            int failUpRate = (int)GameData.DataManager.FieldCommonParam[(int)FieldCommon.ParamIndx.EncFaileUpRate].param;
            uint calcPer = (uint)GameData.DataManager.FieldCommonParam[(int)FieldCommon.ParamIndx.EncBaseRate].param;
            if (inGridmove || !EncountWalkCheck(PlayerWork.WalkEncountCount, per << CALC_SHIFT))
            {
                if (RandomGroupWork.RandomRange(0, 100) >= failUpRate)
                    return false;
            }

            if (AttributeID.MATR_IsLongGrass(attr))
                calcPer += (uint)GameData.DataManager.FieldCommonParam[(int)FieldCommon.ParamIndx.EncLongGrassRate].param;
            else if (PlayerWork.IsFormBicycle())
                calcPer += (uint)GameData.DataManager.FieldCommonParam[(int)FieldCommon.ParamIndx.EncBicycleUpRate].param;

            uint prob = CalendarEnc.CalEnc_GetProb(calcPer, SystemTimeWork.IsPenalty());
            if (prob > 100)
                prob = 100;

            if (!EncountCheckMain(prob))
                return false;

            if (!EncountCheckMain(per))
                return false;

            return true;
        }
		private static bool EncountWalkCheck(float walkcnt, uint per) {
            uint length = (uint)GameData.DataManager.FieldCommonParam[(int)FieldCommon.ParamIndx.EncLength].param;
            uint sub = per / 10;
            if (sub > length)
                sub = length;

            return (float)(length - sub) <= walkcnt;
        }
		private static bool EncountCheckMain(uint per) {
            return RandomGroupWork.RandomRange(0, 100) < per;
        }
