            if (rand < 50)
                return 2;
            if (rand < 60)
                return 3;
            if (rand < 70)
                return 4;
            if (rand < 80)
                return 5;
            if (rand < 85)
                return 6;
            if (rand < 90)
                return 7;
            if (rand < 94)
                return 8;
            if (rand < 98)
                return 9;
            if (rand < 99)
                return 10;
            return 11;
        }
