		private static bool SetEncountData(global::Pml.PokePara.PokemonParam param, global::FishingRod inRodType, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::MonsLv[] inData, int location, global::Dpr.Battle.Logic.BTL_CLIENT_ID inTarget, ref global::Dpr.Field.EncountResult outBattleParam) {
            int no = 0;
            // The six CheckFixTypeEcnt calls are inlined (019b6e54..019b7148). LTO dropped their unused inListNum argument
            // (never loaded), so the value passed here is unrecoverable; inData.Length is written as the natural one.
            bool isFix = CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.HAGANE, TokuseiNo.ZIRYOKU, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.DENKI, TokuseiNo.SEIDENKI, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.KUSA, TokuseiNo.SYUUKAKU, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.HONOO, TokuseiNo.MORAIBI, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.MIZU, TokuseiNo.YOBIMIZU, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.DENKI, TokuseiNo.HIRAISIN, ref no);

            int lv;
            switch (location)
            {
                case FISHING_ENCOUNT:
                    if (!isFix)
                        no = RandomPokeSetFishing(inRodType);
                    lv = SetEncountPokeLv(inData[no], inFldSpa);
                    break;

                case WATER_ENCOUNT:
                    if (!isFix)
                        no = RandomPokeSetNoGround();
                    lv = SetEncountPokeLv(inData[no], inFldSpa);
                    break;

                case GROUND_ENCOUNT:
                    if (!isFix)
                        no = RandomPokeSet();
                    no = GetMaxLvMonsTblNo(inData, inFldSpa, no);
                    lv = inData[no].maxlv;
                    break;

                default:
                    lv = 0;
                    break;
            }

            if (CheckEcntCancelByLv(inFldSpa, param, lv))
                return false;

            if (CheckSpray(lv, ref inFldSpa))
                return false;

            EncountParamSet(inData[no].monsNo, lv, inTarget, inFldSpa, param, ref outBattleParam);
            return true;
        }
		private static bool SetEncountDataDecideMons(global::Pml.MonsNo inMonsNo, uint inLv, global::Dpr.Battle.Logic.BTL_CLIENT_ID inTarget, bool inRare, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::Pml.PokePara.PokemonParam param, ref global::Dpr.Field.EncountResult outBattleParam) {
            if (inRare)
                EncountParamSetRare(inMonsNo, (int)inLv, inTarget, inFldSpa, param, ref outBattleParam);
            else
                EncountParamSet(inMonsNo, (int)inLv, inTarget, inFldSpa, param, ref outBattleParam);

            return true;
        }
		private static bool SetSwayEncountData(global::Pml.PokePara.PokemonParam param, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::MonsLv[] inData, global::Dpr.Battle.Logic.BTL_CLIENT_ID inTarget, ref global::Dpr.Field.EncountResult outBattleParam, global::Pml.MonsNo inMonsNo, uint inLv) {
            int no = 0;
            // Same inlined CheckFixTypeEcnt chain as SetEncountData (019b6b04..019b6c50); inListNum unrecoverable (LTO).
            bool isFix = CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.HAGANE, TokuseiNo.ZIRYOKU, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.DENKI, TokuseiNo.SEIDENKI, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.KUSA, TokuseiNo.SYUUKAKU, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.HONOO, TokuseiNo.MORAIBI, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.MIZU, TokuseiNo.YOBIMIZU, ref no)
                || CheckFixTypeEcnt(inFldSpa, inData, inData.Length, PokeType.DENKI, TokuseiNo.HIRAISIN, ref no);
            if (!isFix)
                no = RandomPokeSet();

            MonsNo monsNo = inData[no].monsNo;
            int lv = inData[no].maxlv;
            if (inMonsNo != MonsNo.NULL)
            {
                if (monsNo == inMonsNo)
                {
                    monsNo = inMonsNo;
                    lv = (int)inLv;
                    SwayGrass.rensa_count++;
                }
                else
                {
                    SwayGrass.SwayGrass_InitSwayGrass();
                }
            }
            else
            {
                SwayGrass.rensa_mons = monsNo;
                SwayGrass.rensa_lv = (uint)lv;
            }

            EncountParamSet(monsNo, lv, inTarget, inFldSpa, param, ref outBattleParam);
            return true;
        }
		private static bool CheckFixTypeEcnt(global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::MonsLv[] inData, int inListNum, global::Pml.PokeType type, global::Pml.TokuseiNo tokusei, ref int outNo) {
            if (inFldSpa.Egg)
                return false;

            if (inFldSpa.Spa != tokusei)
                return false;

            if (RandomGroupWork.RandomValue(2) != 0)
                return false;

            // 019b7c94: tail call; w1 (inListNum) is not reloaded — FixPokeSet never reads it
            return FixPokeSet(inData, inListNum, type, ref outNo);
        }
		private static bool FixPokeSet(global::MonsLv[] inData, int inListNum, global::Pml.PokeType type, ref int outNo) {
            int num = inData.Length;
            int[] list = new int[ENC_MONS_NUM_MAX];
            int count = 0;
            for (int i = 0; i < num; i++)
            {
                uint type1 = calc.PERSONAL_GetParam((int)inData[i].monsNo, 0, Pml.Personal.ParamID.TYPE1);
                uint type2 = calc.PERSONAL_GetParam((int)inData[i].monsNo, 0, Pml.Personal.ParamID.TYPE2);
                if ((PokeType)type1 == type || (PokeType)type2 == type)
                {
                    list[count] = i;
                    count++;
                }
            }

            if (count == 0 || count == num)
                return false;

            outNo = list[RandomGroupWork.RandomValue(10000) % count];
            return true;
        }
		private static int SetEncountPokeLv(global::MonsLv inData, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa) {
            int maxLv;
            int minLv;
            if (inData.maxlv < inData.minlv)
            {
                maxLv = inData.minlv;
                minLv = inData.maxlv;
            }
            else
            {
                maxLv = inData.maxlv;
                minLv = inData.minlv;
            }

#if !SWITCH
            // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
            int lv = global::PcPlatform.PcIntDiv.Rem(RandomGroupWork.RandomValue(10000), maxLv - minLv + 1);
#else
            int lv = RandomGroupWork.RandomValue(10000) % (maxLv - minLv + 1);
#endif

            if (!inFldSpa.Egg && (inFldSpa.Spa == TokuseiNo.PURESSYAA || inFldSpa.Spa == TokuseiNo.HARIKIRI || inFldSpa.Spa == TokuseiNo.YARUKI))
            {
                if (RandomGroupWork.RandomValue(2) != 0)
                    return maxLv;
            }
            return lv + minLv;
        }
		private static void EncountParamSetRare(global::Pml.MonsNo poke, int lv, global::Dpr.Battle.Logic.BTL_CLIENT_ID inTarget, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::Pml.PokePara.PokemonParam inPokeParam, ref global::Dpr.Field.EncountResult outBattleParam) {
            int index = (int)inTarget - 1;
            Seikaku seikaku = Seikaku.NUM;
            if (!inFldSpa.Egg)
            {
                if (inFldSpa.Spa == TokuseiNo.SINKURO)
                {
                    outBattleParam.HatudouTokusei = TokuseiNo.SINKURO;
                    seikaku = inPokeParam.GetSeikaku();
                }
                else if (inFldSpa.Spa == TokuseiNo.MEROMEROBODHI && RandomGroupWork.RandomValue(3) > 0)
                {
                    // 019b7eb8: the tokusei store precedes GetSex here (EncountParamSet stores it after)
                    outBattleParam.HatudouTokusei = TokuseiNo.MEROMEROBODHI;
                    switch (inPokeParam.GetSex())
                    {
                        case Sex.FEMALE:
                            outBattleParam.FixSex[index] = Sex.MALE;
                            break;

                        case Sex.MALE:
                            outBattleParam.FixSex[index] = Sex.FEMALE;
                            break;

                        default:
                            outBattleParam.FixSex[index] = Sex.UNKNOWN;
                            break;
                    }
                }
            }

            outBattleParam.Enemy[index] = poke;
            outBattleParam.Level[index] = lv;
            outBattleParam.FixSeikaku[index] = seikaku;
        }
		private static void EncountParamSet(global::Pml.MonsNo poke, int lv, global::Dpr.Battle.Logic.BTL_CLIENT_ID inTarget, global::Dpr.Field.FieldEncount.ENC_FLD_SPA inFldSpa, global::Pml.PokePara.PokemonParam inPokeParam, ref global::Dpr.Field.EncountResult outBattleParam) {
            int index = inTarget == BTL_CLIENT_ID.BTL_CLIENT_ENEMY1 ? 0 : 1;
            outBattleParam.FixSex[index] = Sex.UNKNOWN;
            Seikaku seikaku = Seikaku.NUM;
            if (!inFldSpa.Egg)
            {
                if (inFldSpa.Spa == TokuseiNo.SINKURO)
                {
                    outBattleParam.HatudouTokusei = TokuseiNo.SINKURO;
                    seikaku = inPokeParam.GetSeikaku();
                }
                else if (inFldSpa.Spa == TokuseiNo.MEROMEROBODHI)
                {
                    byte sexVector = inPokeParam.GetSexVector();
                    if (sexVector >= (byte)Pml.Personal.SexVector.RANDOM_MIN && sexVector <= (byte)Pml.Personal.SexVector.RANDOM_MAX && RandomGroupWork.RandomValue(3) > 0)
                    {
                        Sex sex = inPokeParam.GetSex();
                        outBattleParam.HatudouTokusei = TokuseiNo.MEROMEROBODHI;
                        if (sex == Sex.FEMALE)
                            outBattleParam.FixSex[index] = Sex.MALE;
                        else if (sex == Sex.MALE)
                            outBattleParam.FixSex[index] = Sex.FEMALE;
                    }
                }
            }

            outBattleParam.Enemy[index] = poke;
            outBattleParam.Level[index] = lv;
            outBattleParam.FixSeikaku[index] = seikaku;
        }
		private static void LastTokuseiCheck(ref global::Dpr.Field.EncountResult result, ref global::Dpr.Field.FieldEncount.ENC_FLD_SPA spa) {
            if (result.HatudouTokusei != TokuseiNo.NULL)
                return;

            if (spa.Egg)
                return;

            if (spa.Spa == TokuseiNo.HUKUGAN || spa.Spa == TokuseiNo.KYOUUN)
                result.HatudouTokusei = spa.Spa;
        }
		private static void LastProc(ref global::Dpr.Field.EncountResult result, ref global::Dpr.Field.FieldEncount.ENC_FLD_SPA spa) {
            LastTokuseiCheck(ref result, ref spa);
            for (int i = 0; i < result.Enemy.Length; i++)
            {
                switch (result.Enemy[i])
                {
                    case MonsNo.KARANAKUSI:
                    case MonsNo.TORITODON:
                        result.karanaForm = spa.FormProb[0] != 0 ? 1 : 0;
                        break;

                    case MonsNo.ANNOON:
                        result.annoForm = spa.AnnoonTblType;
                        break;
                }
            }
        }
