		public static global::Pml.MonsNo GetSafariScopeMonster(global::ZoneID zoneId) {
            // 019b8304..019b834c: the fresh array is stored and immediately replaced by the sheet's ground table, which
            // ApplyDayTime / ApplyAgbSlot / SetSfariMonster then modify IN PLACE (shipped).
            MonsLv[] enc_data = new MonsLv[ENC_MONS_NUM_MAX];
            var data = GameManager.GetFieldEncountData(zoneId);
            enc_data = data.ground_mons;
            ApplyDayTime(ref enc_data, data);
            ApplyAgbSlot(ref enc_data, data);
            SetSfariMonster(true, ZukanWork.GetZenkokuFlag(), ref enc_data);
            return enc_data[Pml.Local.Random.GetValue((uint)enc_data.Length)].monsNo;
        }
		private static void SafariEnc_SetSafariEnc(int inRandomSeed, bool inBookGet, global::ZoneID inZoneID, ref global::MonsLv[] outenc_data) {
            int index = (inRandomSeed >> (ZoneWork.SafariZonePosID(inZoneID) * 5)) & 0x1f;
            if (inBookGet)
                index += 32;

            MonsNo monsNo = GameManager.GetSafariMonsNo(index);
            outenc_data[SP_ENC_1].monsNo = monsNo;
            outenc_data[SP_ENC_2].monsNo = monsNo;
        }
		private static int CheckMovePokeEnc() {
            bool[] isExist = new bool[2];
            isExist[0] = false;
            isExist[1] = false;
            bool isAny = false;

            if (EncountDataWork.GetMovePoke_ZoneID(0) == PlayerWork.zoneID)
            {
                var data = new DPData.MV_POKE_DATA();
                EncountDataWork.GetMovePokeData(0, ref data);
                if (data.EncountStatus == 1)
                {
                    isExist[0] = true;
                    isAny = true;
                }
            }

            if (EncountDataWork.GetMovePoke_ZoneID(1) == PlayerWork.zoneID)
            {
                var data = new DPData.MV_POKE_DATA();
                EncountDataWork.GetMovePokeData(1, ref data);
                if (data.EncountStatus == 1)
                {
                    isExist[1] = true;
                    isAny = true;
                }
            }

            if (!isAny)
                return -1;

            // 019b4690: the roll is taken before the table read
            int rand = RandomGroupWork.RandomValue(100);
            if (GameData.DataManager.FieldCommonParam[(int)FieldCommon.ParamIndx.MVPokeEncRate].param > rand)
                return -1;

            // 019b46e0..019b478c: four unrolled probes starting at a random slot, (index + 1) % 2 each step
            int index = RandomGroupWork.RandomRange(0, 2);
            for (int i = 0; i < 4; i++)
            {
                if (isExist[index])
                    return index;

                index = (index + 1) % 2;
            }

            return -1;
        }
